package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/**
 * A sheet's dated settings: the value of each in force on a date is the one with the latest from-date on
 * or before it (a value with no from-date applying from the beginning of time); before every from-date,
 * and where that value was saved blank, the sheet's starting value (1.00 for the floor, 0.00 for the late
 * percent, 14 days for the terms; none for a grade's grace days, the clerk limit, the cap, the proof threshold and the note threshold; the sheet's terms for a grade's own
 * terms).
 */
public record DatedSettings(List<SheetSetting> values) {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String TERMS = "terms";

    public static final String LATE_PCT = "late-pct";

    public static final String CAP = "cap";

    public static final String PROOF_THRESHOLD = "proof-threshold";

    public static final String NOTE_THRESHOLD = "note-threshold";

    /** A sheet with no value saved: every setting has its starting value on every date. */
    public static final DatedSettings NONE = new DatedSettings(List.of());

    public static final String GRACE = "grace";

    /** The key of a grade's grace days: grace-A, grace-B or grace-C. */
    public static String gradeGraceKey(String grade) {
        return GRACE + "-" + grade;
    }

    /** The key of a grade's own terms: terms-A, terms-B or terms-C. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The key's value in force on the date as written; empty when none is (or it was saved blank). */
    public Optional<String> on(String key, LocalDate date) {
        return values.stream()
                .filter(v -> v.getKey().equals(key))
                .filter(v -> v.getFromDate() == null || !v.getFromDate().isAfter(date))
                .max(Comparator.comparing(SheetSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(SheetSetting::getValue);
    }

    /** The least live due a claim dated on the date has. */
    public BigDecimal floor(LocalDate date) {
        return on(FLOOR, date).map(BigDecimal::new).orElse(Sheet.DEFAULT_FLOOR);
    }

    /** The percent an overdue claim gains of its figure for a 30-day boundary past its due-by falling on the date. */
    public BigDecimal latePct(LocalDate date) {
        return on(LATE_PCT, date).map(BigDecimal::new).orElse(Sheet.DEFAULT_LATE_PCT);
    }

    /** The sheet's terms for a claim dated on the date, in days. */
    public int terms(LocalDate date) {
        return on(TERMS, date).map(Integer::valueOf).orElse(Sheet.DEFAULT_TERMS);
    }

    /** The grade's own terms on the date; null when it has none then (it uses the sheet's). */
    public Integer gradeTerms(String grade, LocalDate date) {
        return grade == null ? null : on(gradeTermsKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /**
     * The grade's grace days on the date: the days past a claim's due-by before it is overdue; 0 when the
     * grade has none then (or it was saved blank).
     */
    public int grace(String grade, LocalDate date) {
        return grade == null ? 0 : on(gradeGraceKey(grade), date).map(Integer::valueOf).orElse(0);
    }

    /** The terms that fix the due-by of a claim of the grade dated on the date: the grade's own, or the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = gradeTerms(grade, date);
        return own != null ? own : terms(date);
    }

    /**
     * The terms that fix the due-by of a claim dated on the date for a person with their own terms (null:
     * none) and the grade then: the person's own, else the grade's, else the sheet's.
     */
    public int termsFor(Integer personTerms, String grade, LocalDate date) {
        return personTerms != null ? personTerms : termsFor(grade, date);
    }

    /** The most due a clerk may settle on a claim on the date; null when there is no limit. */
    public BigDecimal clerkLimit(LocalDate date) {
        return on(CLERK_LIMIT, date).map(BigDecimal::new).orElse(null);
    }

    /** The most due a claim dated on the date may have to be settled or approved with no proof; null when there is none. */
    public BigDecimal proofThreshold(LocalDate date) {
        return on(PROOF_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The most due a claim dated on the date may have to be opened with an empty note; null when there is none. */
    public BigDecimal noteThreshold(LocalDate date) {
        return on(NOTE_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The most a person's due-total comes to on the date; null when there is no cap. */
    public BigDecimal cap(LocalDate date) {
        return on(CAP, date).map(BigDecimal::new).orElse(null);
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/**
 * A value of one of a sheet's dated settings (keyed as in the settings form: floor, terms, terms-A,
 * late-pct, clerk-limit, cap, ...), in force from its from-date, or from the beginning of time when it has
 * none. The value is as written; null is a value saved blank.
 */
@Entity
@Table(name = "sheet_setting")
public class SheetSetting {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "setting_key", nullable = false)
    private String key;

    /** The first date the value is in force on; null when it is in force from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "setting_value")
    private String value;

    protected SheetSetting() {
    }

    public SheetSetting(String sheetId, String key, LocalDate fromDate, String value) {
        this.sheetId = sheetId;
        this.key = key;
        this.fromDate = fromDate;
        this.value = value;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getValue() {
        return value;
    }

    public void setValue(String value) {
        this.value = value;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Clock;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.asof.SheetPasts;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.statement.DayEnds;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Loads a sheet by id, starting an empty one when the id was never used, and keeps the sheet's
 * today. The real clock is read only to start a new sheet's today; everything else that depends
 * on the date asks {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final Rollup rollup;
    private final DayEnds dayEnds;
    private final SheetPasts pasts;
    private final ApplicationEventPublisher events;
    private final Clock clock = Clock.systemDefaultZone();

    public SheetService(SheetRepository sheets, SheetSettingRepository settings, Rollup rollup, DayEnds dayEnds,
            SheetPasts pasts, ApplicationEventPublisher events) {
        this.dayEnds = dayEnds;
        this.pasts = pasts;
        this.sheets = sheets;
        this.settings = settings;
        this.rollup = rollup;
        this.events = events;
    }

    public Sheet load(String id, String user) {
        try {
            return loadOrCreate(id, user);
        } catch (DataIntegrityViolationException e) {
            // Another user started the same sheet at the same moment: theirs is the one.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }

    /** The sheet as it stands; refused (404) when it was never loaded. */
    public Sheet get(String id) {
        return sheets.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet"));
    }

    /** The sheet's dated settings: the floor, late percent, terms, clerk limit and cap in force on any date. */
    public DatedSettings settings(String id) {
        return new DatedSettings(settings.findBySheetId(id));
    }

    /** The sheet's policy date as set; null when blank (the sheet's today is the policy date then). */
    public LocalDate policyDate(String id) {
        return sheets.findById(id).map(Sheet::getPolicyDate).orElse(null);
    }

    /** The sheet's period numbering from as set; null when blank (off). */
    public LocalDate periodNumberingFrom(String id) {
        return sheets.findById(id).map(Sheet::getPeriodNumberingFrom).orElse(null);
    }

    /** The sheet's entry date as set; null when blank (off). */
    public LocalDate entryDate(String id) {
        return sheets.findById(id).map(Sheet::getEntryDate).orElse(null);
    }

    /** The date a new claim takes when none is given: the sheet's entry date while set, else its today. */
    public LocalDate claimDate(String id) {
        LocalDate entry = entryDate(id);
        return entry != null ? entry : today(id);
    }

    /** The sheet's grace days as set; null when blank (off). */
    public Integer graceDays(String id) {
        return sheets.findById(id).map(Sheet::getGraceDays).orElse(null);
    }

    /** Whether the sheet is archived: every change to it is refused. */
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** The sheet's today: the date to use for every decision and default date on the sheet. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
    }

    /**
     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
     * at the same moment wait on each other, so no number is given twice or skipped.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.bumpClaimNumber(id) != 1) {
            throw new IllegalStateException("No such sheet " + id);
        }
        return sheets.lastClaimNumber(id);
    }

    /**
     * Change the sheet's today, starting the sheet if it was never loaded. The change has no audit
     * line of its own, only what follows from it ({@link TodayChanged}: the periods past their grace
     * days are closed) and then the figures it moves. The sheet as it stands is first written down as at
     * the end of the today it leaves (see {@link DayEnds} and {@link SheetPasts}), and everyone's due-total
     * on it is announced first ({@link DaySnapshot}).
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        Rollup.Figures before = rollup.figures(id);
        if (!today.equals(sheet.getToday())) {
            events.publishEvent(new DaySnapshot(id, user, List.copyOf(before.people().values())));
            dayEnds.record(id, sheet.getToday());
            pasts.record(id, sheet.getToday());
        }
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(id, user, today));
        rollup.changed(id, user, before);
        return saved;
    }

    private Sheet loadOrCreate(String id, String user) {
        return sheets.findById(id)
                .orElseGet(() -> sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock))));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.access.AccessService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Sheet endpoints. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets")
